CREATE POLICY inspiration_photo_view ON storage.objects FOR SELECT TO authenticated USING (bucket_id='inspiration-photos' AND CASE WHEN split_part(name,'/',1) ~ '^[0-9a-f-]{36}$' THEN EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=split_part(name,'/',1)::uuid AND trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid() OR (c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE))) ELSE false END);
CREATE POLICY inspiration_photo_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='inspiration-photos' AND lower(name) ~ '\.(jpe?g|png|webp)$' AND CASE WHEN split_part(name,'/',1) ~ '^[0-9a-f-]{36}$' THEN EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=split_part(name,'/',1)::uuid AND c.creator_id=auth.uid() AND c.hidden_at IS NULL AND trip_private.feature_on(c.trip_id,'inspiration')) ELSE false END);
CREATE POLICY inspiration_photo_remove ON storage.objects FOR DELETE TO authenticated USING (bucket_id='inspiration-photos' AND CASE WHEN split_part(name,'/',1) ~ '^[0-9a-f-]{36}$' THEN EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=split_part(name,'/',1)::uuid AND c.creator_id=auth.uid()) ELSE false END);